WITH src AS (SELECT * FROM order_items WHERE unit_price >= 320 AND quantity IS NOT NULL), unit_price_bucket_summary AS (SELECT CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END AS unit_price_bucket, COUNT(*) AS order_item_count, MIN(unit_price) AS min_unit_price FROM src GROUP BY CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END) SELECT unit_price_bucket, min_unit_price FROM unit_price_bucket_summary ORDER BY unit_price_bucket DESC;
